class Element {
  constructor(props = {}) {
    this.id = props.id || 0;
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX || 0; 
    this.originY = props.originY || 0;
    this.x = props.x || 0;
    this.y = props.y || 0;
    this.w = props.w || 0;
    this.h = props.h || 0;
    this.scaleX = props.scaleX || 1.0;
    this.scaleY = props.scaleY || 1.0;

    this.fillColor = props.fillColor || color('rgba(0, 0, 0, 100)');
    this.strokeColor = props.strokeColor || color('rgba(0, 0, 0, 0)');
    this.backgroundColor = props.backgroundColor || color('rgba(0, 0, 0, 0)');
    this.offsetColorStop = random(0, 1);
    this.offsetColorStopAccel = random(0.005, 0.03);
    this.gradationStopNoise = random(2.0);
    this.gradientStartAngle = props.gradientStartAngle || 0;
    this.gradientX = props.gradientX || 0;
    this.gradientY = props.gradientY || 0;
    this.gradientStartAngle = random(TWO_PI);
    this.colors = generateColorScheme(palette.colors[randomInt(0, palette.colors.length - 1)], 'monochromatic');
    this.transformType = props.transformType || 0;
    this.originX = this.getTransform(this.transformType).originX;
    this.originY = this.getTransform(this.transformType).originY;
    this.w = this.getTransform(this.transformType).w;
    this.h = this.getTransform(this.transformType).h;
    this.angle = getRandomAngleInRadians(4, 0, TWO_PI);
    this.shapeType = 0;
    if (this.transformType === 0) {
      this.shapeType = random() < 0.5 ? 0 : 1;
    } else if (this.transformType === 1) {
      this.shapeType = random() < 0.5 ? 0 : 1;
    } else if (this.transformType === 3) {
      this.shapeType = random() < 0.5 ? 0 : 1;
    }
    this.delay = random(0.0, 0.3) + 0.7;
    this.shapeScaleX = 1;
    this.shapeScaleY = 1;
    this.anime();
  }

  getTransform = (transformType) => {
		const areaSize = 500;
    const transforms = [
      {
        originX: random(-areaSize * 0.5, areaSize * 0.5),
        originY: random(-areaSize * 0.5, areaSize * 0.5),
        w: random(areaSize / 2, areaSize),
        h: random(areaSize / 2, areaSize),
      },
      {
        originX: random(-areaSize * 0.6, areaSize * 0.6),
        originY: random(-areaSize * 0.6, areaSize * 0.6),
        w: random(10, areaSize / 2),
        h: random(10, areaSize / 2),
      },
      {
        originX: random(-areaSize * 0.7, areaSize * 0.7),
        originY: random(-areaSize * 0.7, areaSize * 0.7),
        w: random(2, 20),
        h: random(50, 800),
      },
      {
        originX: random(-areaSize * 0.8, areaSize * 0.8),
        originY: random(-areaSize * 0.8, areaSize * 0.8),
        w: random(20, 80),
        h: random(20, 80),
      },
    ];
    return transforms[transformType];
  }

  anime = () => {
    gsap.to(this, {
      originX : this.getTransform(this.transformType).originX,
      originY : this.getTransform(this.transformType).originY,
      w : this.getTransform(this.transformType).w,
      h : this.getTransform(this.transformType).h,
      angle: getRandomAngleInRadians(4, 0, TWO_PI),
      duration: 0.5,
      delay: this.delay,
      ease: "expo.inOut",
      onComplete: () => {
        this.delay = 1;
        this.anime();
      },
    });
  }

  run = () => {
    if (!this.isDisplay) return
    push();
    translate(this.originX, this.originY);
    scale(this.scaleX, this.scaleY);
    rotate(this.angle);
    this.drawPattern(this.x, this.y, this.w, this.h, this.shapeScaleX, this.shapeScaleY);
    pop();
  }

  drawPattern = (x, y, w, h, shapeScaleX, shapeScaleY) => {
    push();
    noStroke();
    fill(255);
    this.offsetColorStop += this.offsetColorStopAccel;
    if (this.shapeType === 0) {
      setFillLinearGradient(0, 0, w * 2, 0, this.colors, this.colorStops, this.offsetColorStop, 'center', 'liner');
			rect(x, y, w, h);
    } else {
      setFillRadialGradient(0, 0, 0, 0, 0, this.w, this.colors, this.colorStops, this.offsetColorStop, 'linear', 1.0);

      ellipse(x, y, w, w);
    }
    pop();
  }
}

