class Motif {
  constructor(props = {}) {
    this.isDisplay = props.isDisplay ?? true;
    this.id = props.id || 0;
    this.originX = props.originX || 0; 
    this.originY = props.originY || 0;
    this.x = props.x || 0;
    this.y = props.y || 0;
    this.w = props.w || 100;
    this.h = props.h || 100;
    this.angle = props.angle || 0;
    this.colors = props.colors || palette.colors;
    this.elements = props.elements || [];

    for (var i = 0; i < 80; i++) {
      const element = new Element({ transformType : 0});
      this.elements.push(element);
    }
    for (var i = 0; i < 20; i++) {
      const element = new Element({ transformType : 1});
      this.elements.push(element);
    }
    for (var i = 0; i < 15; i++) {
      const element = new Element({ transformType : 2});
      this.elements.push(element);
    }
    for (var i = 0; i < 5; i++) {
      const element = new Element({ transformType : 3});
      this.elements.push(element);
    }
  }

  run = () => {
    push();
    translate(this.originX, this.originY);
    rotate(this.angle);
    for (let i = 0; i < this.elements.length; i++) {
      const element = this.elements[i];
      element.run();
    }
    pop();
  }
}



