    console.error('Invalid input: colors must be a non-empty array');
    return [];
  }
  const pairs = [];
  for (let i = 0; i < colors.length; i += 2) {
    if (i + 1 < colors.length) {
      pairs.push([colors[i], colors[i + 1]]);
    } else {
      pairs.push([colors[i], colors[0]]);
    }
  }
  return pairs;
