function randomEvenInt(minNum, maxNum) {
  if (minNum % 2 !== 0) {
    minNum++;
  }
  if (maxNum % 2 !== 0) {
    maxNum--;
  }
  if (minNum > maxNum) {
    return null;
  }
  const randomEven = minNum + 2 * Math.floor(Math.random() * ((maxNum - minNum) / 2 + 1));
  return randomEven;
}

