  return randomOdd;
}

// 整数numの約数を昇順で一覧と数を返す
function divisor(num) {
  const results = [];
  const sqrt = Math.Math.floor(Math.sqrt(num));
  // 1から平方根までの約数を求める
  for (let i = 1; i <= sqrt; i++) {
    if (num % i === 0) {
      results.push(i); // 約数を追加
      if (i !== num / i) { // 別の約数がある場合
        results.push(num / i); // その約数も追加
      }
    }
  }
  // 昇順に並び替え
  results.sort((a, b) => a - b);
  return {
    divisors: results,
    count: results.length
  };
}

